CREATE OR REPLACE FUNCTION virer_fonds(
    compte_src INT, compte_dest INT, montant NUMERIC
) RETURNS VOID AS $$
DECLARE
    solde_dispo NUMERIC;
BEGIN
    IF montant IS NULL OR montant IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) OR montant <= 0 THEN
        RAISE EXCEPTION 'Le montant doit être positif et fini';
    END IF;
    SELECT solde INTO solde_dispo FROM comptes WHERE id = compte_src FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Compte source absent';
    END IF;
    IF solde_dispo IS NULL OR solde_dispo IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric) OR solde_dispo < montant THEN
        RAISE EXCEPTION 'Fonds insuffisants : disponible %', solde_dispo;
    END IF;
    UPDATE comptes SET solde = solde - montant WHERE id = compte_src;
    UPDATE comptes SET solde = solde + montant WHERE id = compte_dest AND solde IS NOT NULL AND solde NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric);
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Compte destinataire absent ou solde invalide';
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Erreur transactionnelle : %', SQLERRM;
        RAISE;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION audit_employes_trigger()
RETURNS TRIGGER AS $$
BEGIN
    IF (TG_OP = 'UPDATE') THEN
        INSERT INTO audit_log (table_name, op, row_id, old_val, new_val, modifie_par, modifie_le)
        VALUES ('employes', 'UPDATE', OLD.id, row_to_json(OLD), row_to_json(NEW), current_user, clock_timestamp());
        RETURN NEW;
    ELSIF (TG_OP = 'DELETE') THEN
        INSERT INTO audit_log (table_name, op, row_id, old_val, new_val, modifie_par, modifie_le)
        VALUES ('employes', 'DELETE', OLD.id, row_to_json(OLD), NULL, current_user, clock_timestamp());
        RETURN OLD;
    END IF;
    RETURN NEW;
END; $$ LANGUAGE plpgsql;

